COMMIT;

-- ── Conferencia ──────────────────────────────────────────────────────
-- Esperado: Controle = 75 jogos / 49 colunas / escala_camps {Paulistão 26}
--           Periferico = 74 jogos / 37 colunas
SELECT c.label, c.section_kind, c.escala_camps,
       (SELECT count(*) FROM competition_events e WHERE e.competition_id = c.id) AS jogos,
       (SELECT count(*) FROM competition_columns k WHERE k.competition_id = c.id) AS colunas
FROM competitions c WHERE c.slug IN ('paulistao-a1', 'paulistao-a1-periferico') ORDER BY c.sort_order;

-- Os grupos do Controle do A1 devem ficar IGUAIS aos do Brasileirao:
-- Jogo 10 · Equipe Técnica 13 · Transmissão 13 · FEED B 6 · Técnico 7
SELECT col_group, count(*) AS colunas FROM competition_columns
WHERE competition_id = (SELECT id FROM competitions WHERE slug = 'paulistao-a1')
GROUP BY col_group ORDER BY min(sort_order);

-- Quantos jogos do A1 a Visao Geral vai achar na Escala Geral
-- (0 aqui = o nome do campeonato na escala_geral e diferente)
SELECT count(*) AS jogos_do_a1_na_escala_geral FROM escala_geral WHERE campeonato = 'Paulistão 26';

-- Nenhum resultado aqui = a renomeacao do fornecedor de micros terminou
SELECT count(*) AS sobrou_fornecedor_micros FROM competition_events
WHERE data ? 'fornecedor_micros';